import Parser from 'web-tree-sitter';
import { readFileSync, existsSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export interface ParsedSymbol {
  name: string;
  kind: string;
  startLine: number;
  endLine: number;
  exported: boolean;
}

export interface ParsedImport {
  source: string;
}

export interface ParseResult {
  symbols: ParsedSymbol[];
  imports: ParsedImport[];
}

let _initPromise: Promise<void> | null = null;

async function initOnce(): Promise<void> {
  if (_initPromise) return _initPromise;
  _initPromise = (async () => {
    await Parser.init();
  })();
  return _initPromise;
}

const __dirname =
  typeof __filename !== 'undefined'
    ? dirname(__filename)
    : dirname(fileURLToPath(import.meta.url));
const WASM_DIR = resolve(__dirname, '../../.tree-sitter');

const TS_PARSER_PATH = join(WASM_DIR, 'tree-sitter-typescript.wasm');
const JS_PARSER_PATH = join(WASM_DIR, 'tree-sitter-javascript.wasm');

const TS_PARSER_PROMISE: Promise<Parser> = (async () => {
  await initOnce();
  return Parser.load(TS_PARSER_PATH);
})();

const JS_PARSER_PROMISE: Promise<Parser> = (async () => {
  await initOnce();
  return Parser.load(JS_PARSER_PATH);
})();

export async function parseFile(
  _filePath: string,
  content: string,
  extHint?: string
): Promise<ParseResult> {
  const ext = extHint ?? _filePath.slice(_filePath.lastIndexOf('.'));
  let parser: Parser | null = null;
  if (ext === '.ts' || ext === '.tsx') {
    parser = await TS_PARSER_PROMISE;
  } else if (ext === '.js' || ext === '.jsx' || ext === '.mjs' || ext === '.cjs') {
    parser = await JS_PARSER_PROMISE;
  }
  if (!parser) return { symbols: [], imports: [] };

  const tree = parser.parse(content);
  const symbols: ParsedSymbol[] = [];
  const imports: ParsedImport[] = [];

  collectSymbols(tree.rootNode, symbols);
  collectImports(tree.rootNode, imports);

  return { symbols, imports };
}

function collectSymbols(
  node: Parser.SyntaxNode,
  out: ParsedSymbol[]
): void {
  const kind = node.type;
  if (kind === 'export_statement') {
    const child = node.firstNamedChild;
    if (child) {
      const sym = nodeToSymbol(child);
      if (sym) {
        sym.exported = true;
        out.push(sym);
        return;
      }
    }
  }
  if (
    kind === 'function_declaration' ||
    kind === 'class_declaration' ||
    kind === 'interface_declaration' ||
    kind === 'type_alias_declaration' ||
    kind === 'enum_declaration'
  ) {
    const sym = nodeToSymbol(node);
    if (sym) out.push(sym);
  } else if (kind === 'lexical_declaration') {
    const decls = node.descendantsOfType('variable_declarator');
    for (const d of decls) {
      const nameNode = d.childForFieldName('name');
      if (nameNode && nameNode.type === 'identifier') {
        out.push({
          name: nameNode.text,
          kind: 'const',
          startLine: node.startPosition.row,
          endLine: node.endPosition.row,
          exported: false,
        });
      }
    }
  }
  for (let i = 0; i < node.childCount; i++) {
    const c = node.child(i);
    if (c) collectSymbols(c, out);
  }
}

function nodeToSymbol(node: Parser.SyntaxNode): ParsedSymbol | null {
  let name: string | null = null;
  let kind = 'unknown';
  if (node.type === 'function_declaration') {
    kind = 'function';
    const n = node.childForFieldName('name');
    if (n) name = n.text;
  } else if (node.type === 'class_declaration') {
    kind = 'class';
    const n = node.childForFieldName('name');
    if (n) name = n.text;
  } else if (node.type === 'interface_declaration') {
    kind = 'interface';
    const n = node.childForFieldName('name');
    if (n) name = n.text;
  } else if (node.type === 'type_alias_declaration') {
    kind = 'type';
    const n = node.childForFieldName('name');
    if (n) name = n.text;
  } else if (node.type === 'enum_declaration') {
    kind = 'enum';
    const n = node.childForFieldName('name');
    if (n) name = n.text;
  }
  if (!name) return null;
  return {
    name,
    kind,
    startLine: node.startPosition.row,
    endLine: node.endPosition.row,
    exported: false,
  };
}

function collectImports(
  node: Parser.SyntaxNode,
  out: ParsedImport[]
): void {
  if (node.type === 'import_statement') {
    const src = node.childForFieldName('source');
    if (src) {
      const s = src.text.replace(/^['"]|['"]$/g, '');
      out.push({ source: s });
    }
    return;
  }
  for (let i = 0; i < node.childCount; i++) {
    const c = node.child(i);
    if (c) collectImports(c, out);
  }
}

